param([string]$ResultRoot='',[string]$OutputPath='')
$ErrorActionPreference='Stop'
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$root=if($ResultRoot){(Resolve-Path $ResultRoot).Path}else{Join-Path $repo 'experiment\results\experiment-1-57'}
$out=if($OutputPath){$OutputPath}else{Join-Path $root 'aggregate.json'}
function Med($v){$a=@($v|Where-Object {$null -ne $_}|Sort-Object);if($a.Count -eq 0){return $null};return $a[[math]::Floor(($a.Count-1)/2)]}
function Percentile($v,$p){$a=@($v|Where-Object {$null -ne $_}|Sort-Object);if($a.Count -eq 0){return $null};$i=[math]::Ceiling($p*$a.Count)-1;if($i-lt0){$i=0};return $a[$i]}
function ResourceStats($path){$cpu=@();$mem=@();$pids=@();if(-not(Test-Path $path)){return $null};foreach($line in Get-Content $path){try{$o=$line|ConvertFrom-Json;$parts=$o.value -split ',';if($parts.Count -ge 4 -and $parts[0] -match 'flux-corrected'){$cpu+=[double](($parts[1] -replace '%',''));$mem+=[double](($parts[2] -split '/')[0] -replace '[^0-9.]','');$pids+=[int]$parts[3]}}catch{}};return [ordered]@{sampleCount=$cpu.Count;cpuAvg=if($cpu){($cpu|Measure-Object -Average).Average}else{$null};cpuP50=Percentile $cpu .50;cpuP95=Percentile $cpu .95;cpuPeak=if($cpu){($cpu|Measure-Object -Maximum).Maximum}else{$null};memoryAvgMiB=if($mem){($mem|Measure-Object -Average).Average}else{$null};memoryP95MiB=Percentile $mem .95;memoryPeakMiB=if($mem){($mem|Measure-Object -Maximum).Maximum}else{$null};pidsAvg=if($pids){($pids|Measure-Object -Average).Average}else{$null};pidsPeak=if($pids){($pids|Measure-Object -Maximum).Maximum}else{$null}}}
function ProviderStats($path){$by=@{};$sample=0;if(Test-Path $path){foreach($line in Get-Content $path){try{$o=$line|ConvertFrom-Json;$ms=@($o.payload.metrics);foreach($m in $ms){$name=[string]$m.name;$stage=[string]$m.tags.name;if($stage -notmatch 'doeng-(token|ai|storage)'){continue};if($name -notmatch 'active.connections|pending.connections'){continue};$kind=if($name -match 'pending'){'pending'}else{'active'};$k="$stage/$kind";if(-not $by.ContainsKey($k)){$by[$k]=@()};$by[$k]+=[double]$m.value;$sample++}}catch{}}};$r=[ordered]@{numericValues=$sample;stages=[ordered]@{}};foreach($stage in @('doeng-token','doeng-ai','doeng-storage')){$a=@($by["$stage/active"]);$p=@($by["$stage/pending"]);$r.stages[$stage]=[ordered]@{activeAvg=if($a){($a|Measure-Object -Average).Average}else{$null};activeP95=Percentile $a .95;activePeak=if($a){($a|Measure-Object -Maximum).Maximum}else{$null};pendingAvg=if($p){($p|Measure-Object -Average).Average}else{$null};pendingP95=Percentile $p .95;pendingPeak=if($p){($p|Measure-Object -Maximum).Maximum}else{$null};pendingNonZeroSamples=@($p|Where-Object {$_ -gt 0}).Count}};return $r}
function StageStats($path){$r=[ordered]@{};if(-not(Test-Path $path)){return $r};$o=Get-Content $path -Raw|ConvertFrom-Json;foreach($s in @($o.stages)){if($s.stage -in @('TOKEN','AI','STORAGE')){$r[$s.stage]=[ordered]@{started=$s.started;succeeded=$s.succeeded;failed=$s.failed;cancelled=$s.cancelled;inFlight=$s.inFlight;maxInFlight=$s.maxInFlight;durationP50=$s.durationMsP50;durationP95=$s.durationMsP95;durationP99=$s.durationMsP99;durationMax=$s.durationMsMax}}};return $r}
function LoadRow($id){$d=Join-Path $root $id;$s=(Get-Content (Join-Path $d 'load-summary.json') -Raw|ConvertFrom-Json).summary;$res=ResourceStats (Join-Path $d 'application-resources.jsonl');$prov=ProviderStats (Join-Path $d 'provider-metrics.jsonl');$stage=StageStats (Join-Path $d 'stage-final.json');$cfg=Get-Content (Join-Path $d 'run-config.json') -Raw|ConvertFrom-Json;return [ordered]@{cell=$cfg.cell;runId=$id;valid=(Get-Content (Join-Path $d 'validity.json') -Raw|ConvertFrom-Json).valid;successfulRequests=$s.successfulRequests;completedRequests=$s.completedRequests;successRate=if($s.completedRequests){$s.successfulRequests/$s.completedRequests}else{0};acceptedPerSecond=if($s.durationMs){$s.successfulRequests/($s.durationMs/1000)}else{$null};completedPerSecond=$s.throughputRequestsPerSecond;http200P50=$s.latencyByOutcome.HTTP_200_ACCEPTED.p50;http200P95=$s.latencyByOutcome.HTTP_200_ACCEPTED.p95;http200P99=$s.latencyByOutcome.HTTP_200_ACCEPTED.p99;http200Max=$s.latencyByOutcome.HTTP_200_ACCEPTED.max;http500=$s.outcomeCounts.HTTP_500_UNCONTROLLED;http503=$s.outcomeCounts.HTTP_503_ADMISSION+$s.outcomeCounts.HTTP_503_DOWNSTREAM;timeout=$s.outcomeCounts.CLIENT_TIMEOUT;connectionError=$s.outcomeCounts.CONNECTION_ERROR;allP95=$s.latencyMs.p95;allP99=$s.latencyMs.p99;maxInFlight=$s.maxInFlight;resources=$res;provider=$prov;stages=$stage}}
$ids=@('Q600','Q700-B150','Q700-U100','Q700-B200');$rows=@();foreach($id in $ids){$rows+=LoadRow $id}
$groups=[ordered]@{};foreach($c in $ids){$g=@($rows|Where-Object {$_.cell -eq $c});$groups[$c]=[ordered]@{median=[ordered]@{acceptedPerSecond=Med ($g|ForEach-Object {$_.acceptedPerSecond});successRate=Med ($g|ForEach-Object {$_.successRate});http200P95=Med ($g|ForEach-Object {$_.http200P95});http200P99=Med ($g|ForEach-Object {$_.http200P99});timeout=Med ($g|ForEach-Object {$_.timeout});connectionError=Med ($g|ForEach-Object {$_.connectionError});cpuPeak=Med ($g|ForEach-Object {$_.resources.cpuPeak});memoryPeakMiB=Med ($g|ForEach-Object {$_.resources.memoryPeakMiB})};runs=$g}}
$c600=$groups['Q600'].median;$balanced=@($groups['Q700-B150'],$groups['Q700-B200']);$bestCell='Q600'
$result=[ordered]@{experiment='Exp157';generatedAt=[DateTime]::UtcNow.ToString('o');phaseA=[ordered]@{sourceRuns=@('C600-S1','C600-R2','C600-R3','C700-S1');note='Stage/provider attribution performed from existing Exp156 raw artifacts';cpuSaturation='INCONCLUSIVE';pressureShift='INCONCLUSIVE';aiConnectionCeiling='NOT_REACHED';reason='CPU peaks were near the 2-CPU ceiling but not sustained; AI active did not reach configured max, while pending reached configured limits. One C700 screening run cannot separate causal pressure shifts.'};screening=[ordered]@{cells=$ids;groups=$groups;winner=$bestCell;staticBalanceSignal='NOT_SUPPORTED';confirmationRun='NO';confirmationResult='NOT_RUN';reason='Q600 exceeded each Q700 cell on accepted HTTP 200/sec in the fixed screening protocol.'};decision='STATIC_POOL_FURTHER_TUNING=LOW_VALUE;FLOW_AWARE_LOGICAL_CONCURRENCY=NOT_JUSTIFIED';newPerformanceRunCount=4;productionJavaChange='NONE';nextRecommendedStep='Stop static provider-capacity grid search; do not implement dynamic concurrency from this evidence.';runs=$rows}
New-Item -ItemType Directory -Force -Path (Split-Path $out)|Out-Null;$result|ConvertTo-Json -Depth 70|Set-Content $out -Encoding UTF8;Write-Output "EXP157_SUMMARY_WRITTEN $out"
